pub(crate) fn emit_sums_written(sums: &collections::BTreeMap<Vec<String>, String>, units: &[ParsedView<'_, '_, '_, '_, '_, '_, '_>], used_here: &collections::BTreeSet<String>) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut declared: Vec<collections::BTreeSet<String>> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    declared.reserve(units.iter().size_hint().0); for unit in units.iter() { declared.push(declared_errors(unit.words, unit.items)); }
    for (members, name) in sums.iter() {
        if units.len() < 2 {
            out.insert(nikaia_std::block::Text::from(name.to_string()));
            continue;
        }
        let mut owner: i64 = -1;
        for member in members.iter() {
            if owner >= 0 { break; }
            for at in 0..declared.len() as i64 { if owner < 0 && (*unsafe { nikaia_std::proven::read(&declared, (at) as usize) }).contains(member) { owner = at; } }
        }
        if owner == 0 || owner < 0 && used_here.contains(name) { out.insert(nikaia_std::block::Text::from(name.to_string())); }
    }
    out
}

